{
  "technical_and_design_decisions": [
    "Baseline stack: this increment targets the Spring Cloud Data Flow 1.x-era codebase (Spring Boot 1.3, Spring Integration 4.2.x, Spring Hadoop/SHDP 2.2.x) on Java 8; the generic Spring Framework 6/Java 17 note in the overview text does not apply to these stories.",
    "U1: Add an UNDEPLOYED value to the Mesos deployer SPI deployment-state enum and map the 'application not currently deployed' condition to it instead of UNKNOWN, keeping existing state transitions unchanged.",
    "U2: Expose the existing RabbitBindingCleaner through a new secured REST endpoint following current admin API conventions (controller delegates to the cleaner component; returns per-binding cleanup results; consistent error handling and HTTP status codes).",
    "U3: Optimize the YARN deployer by caching application artifacts/contexts to avoid repeated HDFS uploads and by parallelizing module deployment requests for a stream definition; keep the public deployer SPI contract unchanged.",
    "U4/U5/U7: Perform dependency upgrades via Maven parent/BOM version changes only (SHDP 2.2.1 GA, Spring Integration 4.2.2 GA, Boot and Spring Cloud Build revisions); align Spring/Hadoop/Hive transitive versions and fix only compilation/deprecation fallout, preserving backward compatibility.",
    "U6: Extend the Kafka bus/binder producer configuration so a partitioning key (expression) can be set even when there is a single downstream module, delegating to Kafka native partitioning and preserving per-key message ordering; expose it via the existing bus properties mechanism.",
    "U8: Document HSQL DB limitations for composed jobs in the existing Asciidoc reference documentation (in-memory, single-instance, non-production usage and concurrency/transaction caveats); no code changes.",
    "All changes delivered with JUnit unit tests and, where applicable, integration tests on the existing CI pipeline; no new tooling or frameworks introduced."
  ],
  "assumptions": [
    "One developer (the estimator) performs all work; estimates are pure effort in workdays and exclude calendar waiting such as CI queue delays.",
    "The existing codebase already contains the Mesos deployer SPI, YARN deployer, Kafka and Rabbit bus/binder modules, and the RabbitBindingCleaner component ported from XD.",
    "Test environments (RabbitMQ broker, Kafka cluster, YARN/HDP/CDH test cluster) are already available; environment provisioning effort is negligible and included where relevant.",
    "Point-release dependency upgrades (U4, U5, U7) are drop-in with no intentional breaking API changes; only minor compilation/deprecation fixes are expected and are included in the estimates.",
    "Documentation work uses the existing Asciidoc reference docs; no new documentation infrastructure is needed.",
    "Estimates include unit/integration testing and documentation updates per story, but exclude formal external code review since development is performed solo.",
    "The REST cleanup endpoint for U2 follows existing admin API security and does not require new authentication/authorization mechanisms."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment analysis and technical design",
      "activity_description": "Review all eight user stories, inspect affected modules, confirm upgrade compatibility matrix (SHDP 2.2.1, SI 4.2.2, Boot/Cloud Build), and define the approach per story.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Add UNDEPLOYED status to Mesos SPI",
      "activity_description": "Add UNDEPLOYED to the Mesos deployer state enum, map the not-deployed condition to it, and add/adjust unit tests covering the new status.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Implement Rabbit cleanup REST endpoint",
      "activity_description": "Create the REST controller endpoint that invokes RabbitBindingCleaner, including request/response handling, security alignment with admin endpoints, and error handling.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "U2: Cleanup API integration tests and docs",
      "activity_description": "Add integration tests against a RabbitMQ broker verifying artifact cleanup and document the new endpoint in the reference docs.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "U3: YARN deployer performance analysis and design",
      "activity_description": "Profile current stream/module deployment flow, identify bottlenecks (artifact uploads, sequential module deploys), and design caching/parallelization approach.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "U3: Implement YARN deployer optimizations",
      "activity_description": "Implement artifact/context caching and parallel module deployment in the YARN deployer while preserving the deployer SPI contract.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "U3: Performance validation and tests",
      "activity_description": "Validate deployment-time improvement on a YARN test cluster and add/adjust tests guarding the optimized behavior.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8",
      "activity_name": "U4: Upgrade to SHDP 2.2.1 GA",
      "activity_description": "Update dependency versions to SHDP 2.2.1 GA, align Spring/Hadoop/Hive versions per its backported improvements, and resolve compilation/deprecation issues.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "U4: Regression testing on HDP/CDH targets",
      "activity_description": "Run regression suites against the supported HDP and CDH versions to confirm backward compatibility and retained Hive support.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A10",
      "activity_name": "U5: Upgrade to Spring Integration 4.2.2 GA",
      "activity_description": "Bump SI version to 4.2.2 GA and run the affected integration test suites to verify no regressions.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A11",
      "activity_name": "U6: Implement Kafka partitioning key support",
      "activity_description": "Extend Kafka bus/binder producer configuration to accept a partitioning key when there is a single downstream module, wiring it to native Kafka partitioning.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "U6: Kafka partitioning tests and docs",
      "activity_description": "Add tests verifying partition assignment and per-key ordering with a single downstream module, and document the new property.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A13",
      "activity_name": "U7: Upgrade Boot and Spring Cloud Build revisions",
      "activity_description": "Update Spring Boot and Spring Cloud Build versions in the build, fix resulting build/deprecation issues, and verify the full build passes.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A14",
      "activity_name": "U8: Document HSQL DB limitations for composed jobs",
      "activity_description": "Write reference documentation describing HSQL DB limitations (in-memory, single-instance, non-production, concurrency caveats) when used with composed jobs.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A15",
      "activity_name": "Increment-wide integration testing and CI stabilization",
      "activity_description": "Run the combined test suites across all changed modules together, fix cross-story integration issues, and stabilize CI.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A16",
      "activity_name": "Release notes and final verification",
      "activity_description": "Prepare release notes covering all eight stories and perform final end-to-end verification of the increment.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 23
  }
}

